const pause=ms=>new Promise(r=>setTimeout(r,ms));
function distanceReference(){return typeof netMember!=='undefined'&&netMember?.id?state.players.find(p=>p.memberId===netMember.id)??current():current()}
function tileDistances(reference=distanceReference()){
 const n=state.tiles.length,distances=Array(n).fill(null);distances[reference.pos]=0;let count=0;
 for(let step=1;step<n;step++){const pos=(reference.pos+step)%n;if(pos!==0&&state.players.some(p=>p!==reference&&p.pos===pos))continue;distances[pos]=++count}
 return distances;
}
function distanceBadge(distance,x,y,size){const label=distance===null?'—':String(distance),description=distance===null?'有其他玩家在格，不计入':distance===0?'当前所在格':`距当前位置${distance}格`;return `<g class="tile-distance" pointer-events="none" aria-label="${description}"><title>${description}</title><rect x="${x-13}" y="${y+size/2+3}" width="26" height="13" rx="6" fill="#fffdf7" stroke="#b8c6ad" stroke-width=".7"/><text x="${x}" y="${y+size/2+13}" text-anchor="middle" font-size="10" font-weight="700" fill="${distance===null?'#899382':'#275c48'}">${label}</text></g>`}
function boardPoint(pos,n){const a=pos/n*Math.PI*2-Math.PI/2;return [500+415*Math.cos(a),500+415*Math.sin(a)]}
async function animateAdvance(p,steps,ticket){for(let i=0;i<steps;i++){if(ticket!==epoch)return false;const from=p.pos;advance(p,1,steps-i-1);const {path,jumpedPlayers,stopTraps}=state.lastMove;state.motion={player:state.players.indexOf(p),from,to:p.pos,path,jumpedPlayers,jumped:jumpedPlayers.length>0};playSound('knock');render();await pause(jumpedPlayers.length?340:240);if(ticket!==epoch)return false;state.motion=null;if(stopTraps.length){if(!await animateStopTraps(p,stopTraps,ticket))return false;if(!state.traps?.some(t=>t.tileId===state.tiles[p.pos].id))win(p);break}if(i===steps-1&&!stopTraps.length&&!await animateFraudDisarm(p,ticket))return false;if(state.winner||state.trapVictoryPending||p.pos===0)break}return true}
async function animateReturn(p,ticket){const from=p.pos;p.pos=0;state.motion={player:state.players.indexOf(p),from,to:0};playSound('knock');render();await pause(280);if(ticket!==epoch)return false;state.motion=null;return true}
